 let close=json!({"status":"complete verified local prefix-pool experiment","root":ROOT,"report":format!("{REPORT}/README.md"),"local_qualification_passed":a["local_qualification_passed"],"sdk_requests":2988,"distinct_gnark_exports":102,"proof_public_members":204,"native_core_tests":112,"raw_tests":2,"cubic_tests":6,"field_tests":"unchanged source; inherited qualification","profile_samples":a["profile_samples"],"lost_records":0,"accepted170_sources_and_SDK_unchanged":true,"new_cloud_resources":false,"adopted":false,"goal_achieved":false,"cpu10x_shapes":cpu_met,"next_prior_proof_count":5928,"prefix_pool_workers":8,"optional_lifetime_forecast_bytes":17<<20,"forecast_is_not_upper_bound":true});save(r.join("closeout.json"),&close);
 let mut text=String::from("# Preparation before full-pool entry\n\n");writeln!(text,"The eight-worker preparation-pool candidate {} the frozen local nonregression gate. Production remains unchanged. This is a local Ryzen9950X screen; there is no new C7a or Aeglos measurement.\n",if a["local_qualification_passed"]==true{"passes"}else{"does not pass"}).unwrap();
