 for n in shapes{let c=&a["cases"][n];let l=&c["latency"];writeln!(text,"|{}|{:.6}|{:.6}|{:.6}|{:.6}|{:.6}|{:.1}/{:.1}/{:.1}|",n.trim_end_matches("-w32"),l["accepted"]["request_ms"].as_f64().unwrap(),l["off"]["request_ms"].as_f64().unwrap(),l["on"]["request_ms"].as_f64().unwrap(),c["on_off_geomean"].as_f64().unwrap(),c["on_accepted_geomean"].as_f64().unwrap(),l["accepted"]["whole_process_maxrss_mib"].as_f64().unwrap(),l["off"]["whole_process_maxrss_mib"].as_f64().unwrap(),l["on"]["whole_process_maxrss_mib"].as_f64().unwrap()).unwrap();}
