 let report=Path::new(REPORT);let dest=report.join("artifacts");fs::create_dir_all(&dest).unwrap();fs::write(report.join("README.md"),text).unwrap();let mut files=Vec::new();for folder in ["candidate","native","preflight","preflight-proofs","performance"]{walk(&r.join(folder),&mut files);}for e in fs::read_dir(r).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_file(){files.push(e.path());}}let mut index=BTreeMap::new();let mut raw=BTreeMap::new();for p in files{let rel=p.strip_prefix(r).unwrap();if p.file_name().unwrap()=="perf.data"{raw.insert(rel.display().to_string(),hash(&p));continue;}let ext=p.extension().and_then(|x|x.to_str()).unwrap_or("");if !matches!(ext,"rs"|"json"|"md"|"log"|"txt"|"toml"|"lock"|"proof"|"public"|"bin"){continue;}let target=dest.join(rel);fs::create_dir_all(target.parent().unwrap()).unwrap();fs::copy(&p,&target).unwrap();index.insert(rel.display().to_string(),hash(&target));}assert_eq!(raw.len(),3);for(p,h)in &index{assert_eq!(hash(dest.join(p)),*h);}save(dest.join("artifact-index.json"),&json!({"sha256":index,"raw_profiles_local_only":raw}));println!("Archived{}hashes;3rawprofileslocal;localgate{}",index.len(),a["local_qualification_passed"]);checkpoint("closed");
